// ═══════════════════════════════════════════════════════════════
//  CONFIG  ·  the only node you need to edit
// ═══════════════════════════════════════════════════════════════
const config = {
  // ── Your invoice sheet ──────────────────────────────────────
  sheetUrl: 'PASTE_YOUR_GOOGLE_SHEET_URL_HERE',
  sheetTab: 'Invoices',

  // ── Who the emails come from ────────────────────────────────
  businessName: 'Sycorda',
  senderName: 'Hassan',
  ownerEmail: 'user@example.com',        // the daily digest goes here

  // ── Safety switch ───────────────────────────────────────────
  // false = reminders are saved as Gmail drafts for you to review
  // true  = reminders are sent automatically
  autoSend: false,

  // ── Timing rules ────────────────────────────────────────────
  timezone: 'Asia/Karachi',                  // '' = use this workflow's timezone setting
  sheetDateFormat: 'yyyy-MM-dd', // how dates are typed in your sheet, e.g. 'M/d/yyyy' or 'd/M/yyyy'
  lookbackDays: 60,              // how much email history the AI reads per client
  cooldownHours: 0,             // hold off if payment came up in email this recently
  minDaysBetweenEmails: 5,       // never chase the same invoice more often than this
  escalateAfterDays: 7,          // days after the final reminder before it's flagged for you

  // ── One-tap buttons in the digest (optional) ───────────────
  // Paste the PRODUCTION url of the "Digest Action Link" node here,
  // and replace the secret with any long random string.
  actionLinkUrl: '',
  actionSecret: 'change-me-to-a-long-random-string',

  // ── The reminder sequence ───────────────────────────────────
  // "day" counts from the DUE date (negative = before it's due).
  // Placeholders: {firstName} {invoiceRef} {invoiceIds} {total} {dueDate}
  //               {daysOverdue} {paymentLink} {senderName} {businessName}
  // Any line whose placeholder is empty (e.g. no payment link) is dropped.
  sequence: [
    {
      day: -3,
      name: 'Friendly heads-up',
      subject: 'Heads-up: {invoiceIds} due {dueDate}',
      body: `Hi {firstName},

Quick heads-up that {invoiceRef} for {total} is due on {dueDate}.

You can pay here: {paymentLink}

If anything needs to change on your side first (a PO number, a different billing contact), just reply and I'll sort it out.

Thanks,
{senderName}`,
    },
    {
      day: 1,
      name: 'Gentle nudge',
      subject: 'Reminder: {invoiceIds} was due {dueDate}',
      body: `Hi {firstName},

Just a nudge on {invoiceRef} for {total}, which was due on {dueDate}. These things slip through, I know.

Here's the payment link again: {paymentLink}

Thanks!
{senderName}`,
    },
    {
      day: 7,
      name: 'Check-in',
      subject: 'Checking in on {invoiceIds}',
      body: `Hi {firstName},

Following up on {invoiceRef} ({total}, due {dueDate}). Is anything holding it up on your end, like a missing detail or an approval? Happy to help get it through.

Payment link: {paymentLink}

Best,
{senderName}`,
    },
    {
      day: 14,
      name: 'Ask for a date',
      subject: 'Overdue: {invoiceIds} ({total})',
      body: `Hi {firstName},

We're now {daysOverdue} days past the due date on {invoiceRef} ({total}). Could you let me know when I can expect payment?

If splitting it up or a short extension would make things easier, I'm open to that. I'd just like us to agree on a date.

{paymentLink}

Thanks,
{senderName}`,
    },
    {
      day: 21,
      name: 'Final reminder',
      subject: 'Final reminder: {invoiceIds}',
      body: `Hi {firstName},

I haven't been able to get an update on {invoiceRef} ({total}, due {dueDate}), so I'm reaching out one last time.

Please arrange payment or reply with a firm date this week. If I don't hear back, I'll need to pause any ongoing work until the account is settled.

{paymentLink}

Regards,
{senderName}`,
    },
  ],
};

// ── Sanity checks, so a setup mistake fails loudly instead of silently ──
const problems = [];
if (!/docs\.google\.com\/spreadsheets\/d\//.test(config.sheetUrl)) problems.push('sheetUrl: paste your Google Sheet URL');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(config.ownerEmail) || config.ownerEmail.endsWith('@yourdomain.com')) problems.push('ownerEmail: where should the digest go?');
if (!Array.isArray(config.sequence) || !config.sequence.length) problems.push('sequence: add at least one step');
else if (config.sequence.some((s, i) => i > 0 && s.day <= config.sequence[i - 1].day)) problems.push('sequence: "day" values must go up');
if (problems.length) throw new Error('Config needs attention -> ' + problems.join('  |  '));

config.minDaysBetweenEmails = Math.max(1, Number(config.minDaysBetweenEmails) || 1);

// Tell the rest of the workflow which trigger started this run
const incoming = $input.first()?.json ?? {};
const fromLink = incoming && typeof incoming.query === 'object' && incoming.headers !== undefined;

return [{ json: { ...config, trigger: fromLink ? 'link' : 'schedule', linkQuery: fromLink ? incoming.query : null } }];

// Decides with plain logic (no AI, no API calls) which invoices need something today.
// - Counts from the DUE date, not the sent date
// - Skips paid / stopped / snoozed / flagged invoices
// - Picks the step that matches how late the invoice is NOW, so a missed run catches up
// - Never emails the same invoice twice within minDaysBetweenEmails (safe to re-run)
// - Groups invoices per client, so one client gets one email
const cfg = $('Config').first().json;
const TZ = cfg.timezone || $now.zoneName;
const today = DateTime.now().setZone(TZ).startOf('day');
const seq = cfg.sequence;

const CLOSED = ['paid', 'stopped', 'cancelled', 'canceled', 'void', 'written off', 'needs attention'];

function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number' && isFinite(v)) {
    // Google Sheets serial number (days since 1899-12-30)
    return DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: TZ }).plus({ days: Math.floor(v) });
  }
  const s = String(v).trim();
  for (const f of [cfg.sheetDateFormat, 'yyyy-MM-dd', 'd MMM yyyy', 'MMM d, yyyy', 'd-MMM-yyyy']) {
    if (!f) continue;
    const d = DateTime.fromFormat(s, f, { zone: TZ });
    if (d.isValid) return d.startOf('day');
  }
  const iso = DateTime.fromISO(s, { zone: TZ });
  return iso.isValid ? iso.startOf('day') : null;
}
const toNumber = (v) => (typeof v === 'number' ? v : parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')) || 0);
const daysBetween = (a, b) => Math.round(a.diff(b, 'days').days);

const groups = {};
for (const { json: r } of $input.all()) {
  const id = String(r['Invoice ID'] ?? '').trim();
  const email = String(r['Email'] ?? '').trim().toLowerCase();
  const status = String(r['Status'] || 'Unpaid').trim().toLowerCase();
  if (!id || !email || CLOSED.includes(status)) continue;

  const due = parseDate(r['Due Date']);
  if (!due) continue;                                  // unreadable date: reported in the digest
  const snooze = parseDate(r['Snooze Until']);
  if (snooze && snooze > today) continue;              // the client gave a date, respect it

  const daysOverdue = daysBetween(today, due);          // negative = not due yet
  const lastStep = parseInt(r['Last Step Sent'], 10) || 0;   // 1-based, 0 = nothing sent yet
  const lastSent = parseDate(r['Last Followup']);
  const daysSinceLast = lastSent ? daysBetween(today, lastSent) : Infinity;

  // The step that matches how late this invoice is right now
  let eligible = -1;
  seq.forEach((s, i) => { if (daysOverdue >= s.day) eligible = i; });

  let action = null;
  let step = null;
  if (lastStep >= seq.length) {
    if (daysSinceLast >= cfg.escalateAfterDays) action = 'ESCALATE';
  } else if (eligible + 1 > lastStep && daysSinceLast >= cfg.minDaysBetweenEmails) {
    action = 'FOLLOW_UP';
    step = eligible;
  }
  if (!action) continue;

  const key = `${email}|${action}`;
  const name = String(r['Client Name'] ?? '').trim();
  groups[key] = groups[key] || {
    email,
    clientName: name || email,
    firstName: name.split(/\s+/)[0] || 'there',
    action,
    invoices: [],
  };
  groups[key].invoices.push({
    id,
    amount: toNumber(r['Amount']),
    currency: String(r['Currency'] || 'USD').trim().toUpperCase(),
    dueDate: due.toISODate(),
    daysOverdue,
    paymentLink: String(r['Payment Link'] ?? '').trim(),
    lastStep,
    step,
  });
}

return Object.values(groups).map((g) => {
  const steps = g.invoices.map((i) => i.step).filter((s) => s !== null);
  return { json: { ...g, step: steps.length ? Math.max(...steps) : null, lookbackDays: cfg.lookbackDays } };
});

// Turns this client's Gmail history into a short, clean timeline and fills in the reminder template.
const cfg = $('Config').first().json;
const g = $('One Client at a Time').first().json;
const TZ = cfg.timezone || $now.zoneName;
const now = DateTime.now().setZone(TZ);

// ── 1 · Clean up the raw Gmail messages ─────────────────────────
const raw = $input.all().map((i) => i.json || {});
// If Gmail errored we get an {error} item (or the loop item passed straight through). Don't guess.
const gmailFailed = raw.some((m) => m.error) || raw.some((m) => Array.isArray(m.invoices));

const addressOf = (x) => {
  if (!x) return '';
  if (typeof x === 'string') return x.toLowerCase();
  if (Array.isArray(x.value) && x.value[0]) return String(x.value[0].address || '').toLowerCase();
  return String(x.text || '').toLowerCase();
};
const htmlToText = (h) => (!h ? '' : String(h)
  .replace(/<div class="gmail_quote"[\s\S]*$/i, '')
  .replace(/<(style|script)[\s\S]*?<\/\1>/gi, '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div)>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#39;/g, "'").replace(/&quot;/g, '"'));
// Replies repeat the whole thread underneath. Cut it, so each message is only what's new.
const stripQuoted = (t) => {
  let s = '\n' + String(t || '').replace(/\r/g, '');
  const cuts = [
    /\nOn [^\n]{0,200}(\n[^\n]{0,200})?wrote:/i,   // Gmail / Apple Mail
    /\n-{2,} ?Original Message ?-{2,}/i,           // Outlook (old)
    /\nFrom: [^\n]+\n(Sent|Date): /i,              // Outlook
    /\n_{8,}/,                                      // Outlook separator
    /\n-- \n/,                                      // signature
  ];
  for (const p of cuts) {
    const at = s.search(p);
    if (at >= 0) s = s.slice(0, at);
  }
  s = s.split('\n').filter((l) => !l.trim().startsWith('>')).join('\n');
  s = s.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  return s.length > 700 ? s.slice(0, 700) + ' ...' : s;
};
const timeOf = (m) => {
  for (const c of [m.date, m.headers && m.headers.date]) {
    if (!c) continue;
    const d = DateTime.fromJSDate(new Date(c));
    if (d.isValid) return d.setZone(TZ);
  }
  if (m.internalDate) {
    const d = DateTime.fromMillis(Number(m.internalDate));
    if (d.isValid) return d.setZone(TZ);
  }
  return null;
};

const msgs = (gmailFailed ? [] : raw)
  .filter((m) => (m.id || m.threadId) && !(m.labelIds || []).includes('DRAFT'))
  .map((m) => ({
    at: timeOf(m),
    dir: addressOf(m.from || (m.headers && m.headers.from)).includes(g.email) ? 'CLIENT' : 'US',
    subject: String(m.subject || (m.headers && m.headers.subject) || '').trim(),
    body: stripQuoted(m.text || htmlToText(m.html) || m.snippet || ''),
  }))
  .filter((m) => m.at)
  .sort((a, b) => a.at.toMillis() - b.at.toMillis())
  .slice(-12);

// ── 2 · Rule-based checks (cheap, so the AI only runs when it adds value) ──
const ids = g.invoices.map((i) => i.id);
const MONEY = /\b(invoices?|payments?|paid|pay|remit(tance)?|transfer(red)?|wire[ds]?|receipt|overdue|outstanding|balance)\b/i;
const aboutInvoice = (m) => {
  const t = `${m.subject}\n${m.body}`;
  return ids.some((id) => t.toLowerCase().includes(id.toLowerCase())) || MONEY.test(t);
};
const lastMoneyMsg = [...msgs].reverse().find(aboutInvoice);
const hoursSinceInvoiceTalk = lastMoneyMsg ? Math.max(0, Math.round(now.diff(lastMoneyMsg.at, 'hours').hours)) : null;
const lastClient = [...msgs].reverse().find((m) => m.dir === 'CLIENT');
const lastClientMessage = lastClient ? `${lastClient.at.toFormat('LLL d')}: ${lastClient.body.replace(/\s+/g, ' ').slice(0, 240)}` : '';

let preDecision = '';
let preReason = '';
if (g.action === 'ESCALATE') {
  preDecision = 'ESCALATE';
  preReason = `All ${cfg.sequence.length} reminders went out and it's still unpaid. Worth a personal call.`;
} else if (gmailFailed) {
  preDecision = 'SKIP';
  preReason = "Couldn't read the email history, so nothing was sent. Will retry next run.";
} else if (hoursSinceInvoiceTalk !== null && hoursSinceInvoiceTalk < cfg.cooldownHours) {
  preDecision = 'SKIP';
  preReason = `Payment came up in email ${hoursSinceInvoiceTalk}h ago, so holding off to avoid double-chasing.`;
} else if (!msgs.length) {
  preDecision = 'SEND';
  preReason = `No emails with this client in the last ${cfg.lookbackDays} days, so the template was used as written (no AI call needed).`;
}

// ── 3 · Fill in the template for this step ──────────────────────
const money = (n, cur) => {
  const c = String(cur || 'USD').trim().toUpperCase();
  try { return new Intl.NumberFormat('en-US', { style: 'currency', currency: c }).format(n); }
  catch (e) { return `${c} ${Number(n || 0).toFixed(2)}`; }
};
const listJoin = (arr) => (arr.length <= 1 ? (arr[0] || '') : `${arr.slice(0, -1).join(', ')} and ${arr[arr.length - 1]}`);
const totals = {};
g.invoices.forEach((i) => { totals[i.currency] = (totals[i.currency] || 0) + i.amount; });
const dues = g.invoices.map((i) => DateTime.fromISO(i.dueDate, { zone: TZ })).sort((a, b) => a.toMillis() - b.toMillis());
const links = [...new Set(g.invoices.map((i) => i.paymentLink).filter(Boolean))];

const vars = {
  firstName: g.firstName,
  invoiceRef: (ids.length > 1 ? 'invoices ' : 'invoice ') + listJoin(ids),
  invoiceIds: ids.join(' & '),
  total: Object.entries(totals).map(([c, n]) => money(n, c)).join(' + '),
  dueDate: dues[0] ? dues[0].toFormat('LLL d') : '',
  daysOverdue: String(Math.max(0, ...g.invoices.map((i) => i.daysOverdue))),
  paymentLink: links.length <= 1 ? (links[0] || '') : g.invoices.filter((i) => i.paymentLink).map((i) => `${i.id}: ${i.paymentLink}`).join('\n'),
  senderName: cfg.senderName,
  businessName: cfg.businessName,
};
const fill = (s) => String(s || '').replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '');
const render = (tpl) => String(tpl || '').split('\n')
  .filter((line) => [...line.matchAll(/\{(\w+)\}/g)].every((m) => String(vars[m[1]] ?? '').trim() !== ''))
  .map(fill).join('\n').replace(/\n{3,}/g, '\n\n').trim();

const step = g.step !== null && g.step !== undefined ? cfg.sequence[g.step] : null;
const invoiceSummary = g.invoices
  .map((i) => `- ${i.id}: ${money(i.amount, i.currency)}, due ${i.dueDate} (${i.daysOverdue >= 0 ? `${i.daysOverdue} days overdue` : `due in ${-i.daysOverdue} days`})`)
  .join('\n');

return [{
  json: {
    email: g.email,
    clientName: g.clientName,
    firstName: g.firstName,
    action: g.action,
    invoices: g.invoices,
    invoiceSummary,
    stepNumber: step ? g.step + 1 : null,
    totalSteps: cfg.sequence.length,
    stepName: step ? step.name : 'Escalation',
    subject: step ? fill(step.subject) : '',
    templateBody: step ? render(step.body) : '',
    transcript: msgs
      .map((m) => `[${m.at.toFormat('yyyy-MM-dd HH:mm')}] ${m.dir === 'CLIENT' ? 'CLIENT -> US' : 'US -> CLIENT'}${m.subject ? ' | ' + m.subject : ''}\n${m.body || '(no text)'}`)
      .join('\n\n---\n\n'),
    messageCount: msgs.length,
    hoursSinceInvoiceTalk,
    lastClientMessage,
    today: now.toFormat('cccc, yyyy-MM-dd'),
    businessName: cfg.businessName,
    senderName: cfg.senderName,
    autoSend: cfg.autoSend === true,
    needsAI: !preDecision,
    preDecision,
    preReason,
  },
}];

