{
  "type": "object",
  "properties": {
    "decision": {
      "type": "string",
      "enum": [
        "SEND",
        "SNOOZE",
        "ESCALATE",
        "SKIP"
      ]
    },
    "clientSignal": {
      "type": "string",
      "enum": [
        "NONE",
        "PROMISED_PAYMENT",
        "CLAIMS_PAID",
        "DISPUTE",
        "HARDSHIP",
        "UNANSWERED_QUESTION",
        "OUT_OF_OFFICE",
        "RECENTLY_AGREED"
      ]
    },
    "snoozeUntil": {
      "type": "string",
      "description": "YYYY-MM-DD when decision is SNOOZE, otherwise empty string"
    },
    "reason": {
      "type": "string",
      "description": "One short sentence for the owner"
    },
    "emailBody": {
      "type": "string",
      "description": "Final plain-text email when decision is SEND, otherwise empty string"
    }
  },
  "required": [
    "decision",
    "clientSignal",
    "snoozeUntil",
    "reason",
    "emailBody"
  ],
  "additionalProperties": false
}

