// Combines the AI verdict (or the rule-based one) and applies guardrails before anything goes out.
const ctx = $('Build Conversation Context').first().json;
const cfg = $('Config').first().json;
const TZ = cfg.timezone || $now.zoneName;
const today = DateTime.now().setZone(TZ).startOf('day');
const ALLOWED = ['SEND', 'SNOOZE', 'ESCALATE', 'SKIP'];

let decision;
let reason;
let clientSignal = 'NONE';
let emailBody = '';
let snoozeUntil = '';
const guardrails = [];

if (!ctx.needsAI) {
  decision = ctx.preDecision;
  reason = ctx.preReason;
} else {
  let o = $input.first().json.output;
  if (typeof o === 'string') { try { o = JSON.parse(o); } catch (e) { o = null; } }
  if (o && typeof o === 'object' && !o.decision && o.output) o = o.output;
  if (o && typeof o === 'object' && o.decision) {
    decision = String(o.decision).trim().toUpperCase();
    reason = String(o.reason || '').trim();
    clientSignal = String(o.clientSignal || 'NONE').trim().toUpperCase();
    emailBody = String(o.emailBody || '').trim();
    snoozeUntil = String(o.snoozeUntil || '').trim();
  } else {
    decision = 'SKIP';
    reason = 'AI review failed, so nothing was sent. Will retry next run.';
  }
}
if (!ALLOWED.includes(decision)) {
  guardrails.push(`unknown decision "${decision}", held off`);
  decision = 'SKIP';
}

if (decision === 'SEND') {
  emailBody = emailBody.replace(/^subject:.*\n+/i, '').trim();
  if (!emailBody) emailBody = ctx.templateBody;

  // 1. Invoice numbers and payment links must survive any AI edit
  const mustKeep = ctx.invoices.flatMap((i) => [i.id, i.paymentLink]).filter((k) => k && ctx.templateBody.includes(k));
  const missing = mustKeep.filter((k) => !emailBody.includes(k));
  if (missing.length) {
    guardrails.push(`AI edit dropped ${missing.join(', ')}, used the original template`);
    emailBody = ctx.templateBody;
  }
  // 2. No unfilled placeholders like {name} or [Your Name]
  if (/\{[a-zA-Z]+\}|\[[^\]]*(name|date|amount|link)[^\]]*\]/i.test(emailBody) && emailBody !== ctx.templateBody) {
    guardrails.push('placeholder left in AI edit, used the original template');
    emailBody = ctx.templateBody;
  }
  // 3. No essays: a reminder should stay roughly the length you wrote
  if (emailBody.length > ctx.templateBody.length * 2.5 + 200) {
    guardrails.push('AI edit was too long, used the original template');
    emailBody = ctx.templateBody;
  }
  if (!reason) reason = 'Reminder looks appropriate.';
}

if (decision === 'SNOOZE') {
  const s = DateTime.fromISO(snoozeUntil, { zone: TZ }).startOf('day');
  if (s.isValid && s > today && s <= today.plus({ days: 45 })) {
    snoozeUntil = s.toISODate();
  } else {
    snoozeUntil = today.plus({ days: 7 }).toISODate();
    guardrails.push('snooze date missing or unrealistic, paused 7 days');
  }
}

const { transcript, ...rest } = ctx;
return [{ json: { ...rest, decision, reason, clientSignal, emailBody, snoozeUntil, guardrails: guardrails.join('; ') } }];

// Works out what to write back to the sheet for every invoice in this client's batch.
const d = $('Apply Guardrails to Decision').first().json;
const cfg = $('Config').first().json;
const TZ = cfg.timezone || $now.zoneName;
const now = DateTime.now().setZone(TZ);
const today = now.toISODate();
const stamp = now.toFormat('yyyy-MM-dd HH:mm');
const res = $input.first().json || {};

let outcome = d.decision;
let failure = '';
if (d.decision === 'SEND') {
  // Gmail returns an id for both sent messages and drafts. No id = it didn't work.
  const ok = !res.error && Boolean(res.id || res.threadId);
  outcome = ok ? (d.autoSend ? 'SENT' : 'DRAFTED') : 'FAILED';
  if (!ok) failure = res.error ? String(res.error.message || res.error) : 'Gmail did not return a message id';
}
const notes = [d.reason, d.guardrails].filter(Boolean).join(' | ');

const updates = d.invoices.map((inv) => {
  const u = { 'Invoice ID': inv.id, 'AI Notes': notes };
  if (outcome === 'SENT' || outcome === 'DRAFTED') {
    const stepNo = (inv.step ?? d.stepNumber - 1) + 1;
    u['Last Step Sent'] = stepNo;
    u['Last Followup'] = today;
    u['Last Action'] = `${outcome === 'SENT' ? '📤 Sent' : '📝 Drafted'} step ${stepNo}/${d.totalSteps} (${stamp})`;
  } else if (outcome === 'SNOOZE') {
    u['Snooze Until'] = d.snoozeUntil;
    u['Last Action'] = `💤 Snoozed until ${d.snoozeUntil} (${stamp})`;
  } else if (outcome === 'ESCALATE') {
    u['Status'] = 'Needs Attention';
    u['Last Action'] = `🚩 Flagged for you (${stamp})`;
  } else if (outcome === 'FAILED') {
    u['Status'] = 'Needs Attention';
    u['Last Action'] = `❌ Email failed (${stamp})`;
    u['AI Notes'] = failure;
  } else {
    u['Last Action'] = `⏭️ Held off (${stamp})`;
  }
  return u;
});

return [{
  json: {
    client: d.clientName,
    email: d.email,
    outcome,
    reason: outcome === 'FAILED' ? failure : notes,
    stepNumber: d.stepNumber,
    totalSteps: d.totalSteps,
    invoices: d.invoices,
    lastClientMessage: d.lastClientMessage,
    clientSignal: d.clientSignal,
    updates,
  },
}];

// Sends one clean summary item back into the loop (collected for the digest at the end).
const { updates, ...report } = $('Prepare Sheet Updates').first().json;
const sheetError = $input.all().map((i) => i.json && i.json.error).find(Boolean);
return [{ json: { ...report, sheetError: sheetError ? String(sheetError.message || sheetError) : '' } }];

// Builds one HTML email summarising today's run. Returns nothing if there's nothing to report.
const cfg = $('Config').first().json;
const TZ = cfg.timezone || $now.zoneName;
const today = DateTime.now().setZone(TZ).startOf('day');
const results = $input.all().map((i) => i.json).filter((r) => r && r.outcome);
if (!results.length) return [];

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const money = (n, cur) => {
  const c = String(cur || 'USD').trim().toUpperCase();
  try { return new Intl.NumberFormat('en-US', { style: 'currency', currency: c }).format(n); }
  catch (e) { return `${c} ${Number(n || 0).toFixed(2)}`; }
};
const sumText = (obj) => Object.entries(obj).map(([c, n]) => money(n, c)).join(' + ') || money(0, 'USD');
const toNumber = (v) => (typeof v === 'number' ? v : parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')) || 0);
function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number' && isFinite(v)) return DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: TZ }).plus({ days: Math.floor(v) });
  const s = String(v).trim();
  for (const f of [cfg.sheetDateFormat, 'yyyy-MM-dd', 'd MMM yyyy', 'MMM d, yyyy', 'd-MMM-yyyy']) {
    if (!f) continue;
    const d = DateTime.fromFormat(s, f, { zone: TZ });
    if (d.isValid) return d.startOf('day');
  }
  const iso = DateTime.fromISO(s, { zone: TZ });
  return iso.isValid ? iso.startOf('day') : null;
}

// ── Portfolio snapshot (the sheet as it was at the start of this run) ──
const CLOSED = ['paid', 'stopped', 'cancelled', 'canceled', 'void', 'written off'];
const openTotals = {};
const overdueTotals = {};
let overdueCount = 0;
const unreadable = [];
for (const { json: r } of $('Read Invoices').all()) {
  if (!r['Invoice ID']) continue;
  if (CLOSED.includes(String(r['Status'] || 'unpaid').trim().toLowerCase())) continue;
  const cur = String(r['Currency'] || 'USD').trim().toUpperCase();
  const amt = toNumber(r['Amount']);
  openTotals[cur] = (openTotals[cur] || 0) + amt;
  const due = parseDate(r['Due Date']);
  if (!due) { unreadable.push(r['Invoice ID']); continue; }
  if (due < today) { overdueTotals[cur] = (overdueTotals[cur] || 0) + amt; overdueCount += 1; }
}

// ── One-tap action links (only if the webhook url is configured) ──
const link = (id, action, extra = '') =>
  `${cfg.actionLinkUrl}?invoice=${encodeURIComponent(id)}&action=${action}${extra}&token=${encodeURIComponent(cfg.actionSecret)}`;
const buttons = (id) => (!cfg.actionLinkUrl ? '' :
  '<div style="margin-top:6px;font-size:13px">'
  + `<a href="${esc(link(id, 'paid'))}" style="color:#188038;text-decoration:none;font-weight:600">✅ Mark paid</a> &nbsp;·&nbsp; `
  + `<a href="${esc(link(id, 'snooze', '&days=7'))}" style="color:#9334e6;text-decoration:none;font-weight:600">💤 Snooze 7d</a> &nbsp;·&nbsp; `
  + `<a href="${esc(link(id, 'stop'))}" style="color:#5f6368;text-decoration:none;font-weight:600">⏸️ Stop chasing</a></div>`);

const card = (r) => {
  const inv = (r.invoices || []).map((i) => `<div style="margin-top:8px"><b>${esc(i.id)}</b> · ${esc(money(i.amount, i.currency))} · ${i.daysOverdue >= 0 ? `${esc(i.daysOverdue)} days overdue` : `due in ${esc(-i.daysOverdue)} days`}${buttons(i.id)}</div>`).join('');
  const step = r.stepNumber ? `<span style="color:#80868b"> · step ${esc(r.stepNumber)}/${esc(r.totalSteps)}</span>` : '';
  const quote = r.lastClientMessage && ['ESCALATE', 'SNOOZE'].includes(r.outcome)
    ? `<div style="margin-top:8px;padding:8px 10px;background:#f8f9fa;border-radius:6px;color:#3c4043;font-size:13px">💬 ${esc(r.lastClientMessage)}</div>` : '';
  const sheetErr = r.sheetError ? `<div style="color:#d93025;font-size:12px;margin-top:6px">Sheet update failed: ${esc(r.sheetError)}</div>` : '';
  return `<div style="padding:14px 0;border-top:1px solid #eee"><div><b>${esc(r.client)}</b> <span style="color:#80868b">&lt;${esc(r.email)}&gt;</span>${step}</div>`
    + `<div style="margin-top:4px;color:#3c4043">${esc(r.reason)}</div>${quote}${inv}${sheetErr}</div>`;
};

const sections = [
  { outcomes: ['ESCALATE', 'FAILED'], title: '🚩 Needs you', color: '#d93025' },
  { outcomes: ['DRAFTED'], title: '📝 Drafts waiting in Gmail', color: '#1a73e8', note: '<a href="https://mail.google.com/mail/u/0/#drafts" style="color:#1a73e8;font-size:13px">Open drafts</a>' },
  { outcomes: ['SENT'], title: '📤 Reminders sent', color: '#1a73e8' },
  { outcomes: ['SNOOZE'], title: '💤 Snoozed (client gave a date)', color: '#9334e6' },
  { outcomes: ['SKIP'], title: '⏭️ Held off today', color: '#80868b' },
];
let body = '';
for (const s of sections) {
  const rows = results.filter((r) => s.outcomes.includes(r.outcome));
  if (!rows.length) continue;
  body += `<div style="margin:24px 0 4px;padding-left:10px;border-left:4px solid ${s.color}"><b style="font-size:15px">${s.title} (${rows.length})</b>${s.note ? ' &nbsp;' + s.note : ''}</div>`;
  body += rows.map(card).join('');
}
if (unreadable.length) {
  body += `<p style="color:#b06000;font-size:13px;margin-top:20px">⚠️ Couldn't read the Due Date on: ${esc(unreadable.join(', '))}. Check sheetDateFormat in Config.</p>`;
}

const count = (list) => results.filter((r) => list.includes(r.outcome)).length;
const needs = count(['ESCALATE', 'FAILED']);
const headline = `${sumText(overdueTotals)} overdue across ${overdueCount} invoice${overdueCount === 1 ? '' : 's'}`;
const html = `<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:620px;color:#202124;font-size:14px;line-height:1.45">
<div style="font-size:12px;color:#80868b;text-transform:uppercase;letter-spacing:.06em">Invoice Autopilot · ${esc(today.toFormat('ccc d LLL yyyy'))}</div>
<div style="font-size:22px;font-weight:700;margin:6px 0 2px">${esc(headline)}</div>
<div style="color:#5f6368">Open balance ${esc(sumText(openTotals))} · ${count(['SENT', 'DRAFTED'])} reminder(s) ${cfg.autoSend ? 'sent' : 'drafted'} · ${needs} need you</div>
${body}
<p style="color:#9aa0a6;font-size:12px;margin-top:28px">From your Invoice Autopilot workflow.</p></div>`;

const subject = `${needs ? `🚩 ${needs} need you · ` : ''}AR digest: ${headline}`;
return [{ json: { to: cfg.ownerEmail, subject, html } }];

// Handles the Paid / Snooze / Stop links in the digest email.
// Two taps on purpose: the first shows a confirm page, so email link-scanners can't trigger changes.
const cfg = $input.first().json;          // Config output, passed through the IF
const q = cfg.linkQuery || {};
const TZ = cfg.timezone || $now.zoneName;
const now = DateTime.now().setZone(TZ);
const stamp = now.toFormat('yyyy-MM-dd HH:mm');

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const page = (icon, title, text, button = '') => `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title></head>`
  + '<body style="margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#f4f5f7;font-family:-apple-system,Segoe UI,Roboto,sans-serif">'
  + '<div style="background:#fff;max-width:420px;margin:24px;padding:32px;border-radius:16px;box-shadow:0 4px 24px rgba(0,0,0,.08);text-align:center">'
  + `<div style="font-size:44px">${icon}</div><h2 style="margin:12px 0 8px;color:#111">${esc(title)}</h2><p style="color:#555;line-height:1.5">${text}</p>${button}</div></body></html>`;

const id = String(q.invoice || '').trim();
const action = String(q.action || '').trim().toLowerCase();
const days = Math.min(60, Math.max(1, parseInt(q.days, 10) || 7));
const secret = String(cfg.actionSecret || '');
const secretOk = secret.length >= 12 && !secret.startsWith('change-me') && q.token === secret;

if (!secretOk || !/^[A-Za-z0-9._\-\/# ]{1,64}$/.test(id) || !['paid', 'snooze', 'stop'].includes(action)) {
  return [{ json: { 'Invoice ID': '', page: page('⛔', 'Link not valid', 'This link is invalid, or the secret in Config has changed.') } }];
}

const label = { paid: `Mark ${id} as paid`, snooze: `Pause reminders for ${id} for ${days} days`, stop: `Stop chasing ${id}` }[action];

if (String(q.confirm) !== '1') {
  const qs = Object.entries({ ...q, confirm: '1' }).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');
  const btn = `<a href="?${esc(qs)}" style="display:inline-block;margin-top:12px;padding:12px 22px;background:#111;color:#fff;border-radius:10px;text-decoration:none;font-weight:600">Yes, confirm</a>`;
  return [{ json: { 'Invoice ID': '', page: page('👆', 'Confirm', `${esc(label)}?`, btn) } }];
}

// Only real sheet columns from here on (the next node writes them straight into the sheet)
const u = { 'Invoice ID': id };
if (action === 'paid') {
  u['Status'] = 'Paid';
  u['Snooze Until'] = '';
  u['Last Action'] = `✅ Marked paid from digest (${stamp})`;
} else if (action === 'snooze') {
  u['Status'] = 'Unpaid';
  u['Snooze Until'] = now.plus({ days }).toISODate();
  u['Last Action'] = `💤 Paused ${days} days from digest (${stamp})`;
} else {
  u['Status'] = 'Stopped';
  u['Last Action'] = `⏸️ Stopped from digest (${stamp})`;
}
return [{ json: u }];
